parameters.jsCode:
const request = $json.output;

const permissions = {
  read_file: true,
  search_repository: true,
  send_email: false,
  delete_database: false
};

const tool = request.tool;

const allowed = permissions[tool] === true;

return [
  {
    json: {
      tool: tool,
      arguments: request.arguments,
      reason: request.reason,
      permission: allowed ? "ALLOWED" : "DENIED"
    }
  }
];

const request = $json;

const riskProfiles = {
  read_file: {
    impact: 1,
    privilege: 1,
    dataSensitivity: 2,
    externalSideEffect: 0
  },

  search_repository: {
    impact: 2,
    privilege: 2,
    dataSensitivity: 3,
    externalSideEffect: 0
  },

  send_email: {
    impact: 5,
    privilege: 4,
    dataSensitivity: 5,
    externalSideEffect: 8
  },

  delete_database: {
    impact: 10,
    privilege: 10,
    dataSensitivity: 10,
    externalSideEffect: 10
  }
};

const profile = riskProfiles[request.tool];

if (!profile) {
  return [
    {
      json: {
        ...request,
        riskScore: 10,
        riskLevel: "CRITICAL",
        error: "Unknown tool"
      }
    }
  ];
}

const riskScore =
  0.30 * profile.impact +
  0.25 * profile.privilege +
  0.25 * profile.dataSensitivity +
  0.20 * profile.externalSideEffect;

let riskLevel;

if (riskScore < 3) {
  riskLevel = "LOW";
} else if (riskScore < 6) {
  riskLevel = "MEDIUM";
} else if (riskScore < 8) {
  riskLevel = "HIGH";
} else {
  riskLevel = "CRITICAL";
}

return [
  {
    json: {
      ...request,

      risk: {
        impact: profile.impact,
        privilege: profile.privilege,
        dataSensitivity: profile.dataSensitivity,
        externalSideEffect: profile.externalSideEffect,
        score: Number(riskScore.toFixed(2)),
        level: riskLevel
      }
    }
  }
];

const request = $json;

let decision;

if (request.permission === "DENIED") {
  decision = "DENY";
} 
else if (request.risk.level === "CRITICAL") {
  decision = "REQUIRE_APPROVAL";
} 
else if (request.risk.level === "HIGH") {
  decision = "REQUIRE_APPROVAL";
} 
else {
  decision = "ALLOW";
}

return [
  {
    json: {
      ...request,
      decision: decision
    }
  }
];

const request = $json;

let executionResult;

switch (request.tool) {

  case "read_file":
    executionResult = {
      status: "SUCCESS",
      message: `Mock read_file executed for ${request.arguments.path}`
    };
    break;

  case "search_repository":
    executionResult = {
      status: "SUCCESS",
      message: `Mock repository search executed`
    };
    break;

  case "send_email":
    executionResult = {
      status: "SUCCESS",
      message: `Mock email operation executed`
    };
    break;

  default:
    executionResult = {
      status: "FAILED",
      message: "Unknown tool"
    };
}

return [
  {
    json: {
      ...request,
      execution: executionResult
    }
  }
];

const request = $json;

return [
  {
    json: {
      ...request,

      execution: {
        status: "BLOCKED",
        message: "Tool execution blocked by SecureMCP policy"
      }
    }
  }
];

const request = $json;

// SIMULATED HUMAN APPROVAL
// Change this to "REJECTED" to simulate rejection.

const humanDecision = "APPROVED";

return [
  {
    json: {
      ...request,

      approval_required: true,

      approval_status: humanDecision,

      approval_timestamp: new Date().toISOString(),

      approval_message:
        humanDecision === "APPROVED"
          ? "Human approved the requested operation."
          : "Human rejected the requested operation."
    }
  }
];

const request = $json;

let executionResult;

switch (request.tool) {

  case "read_file":
    executionResult = {
      status: "SUCCESS",
      tool: "read_file",
      message: `Mock file read executed for: ${
        request.arguments?.path || "unknown"
      }`
    };
    break;

  case "search_repository":
    executionResult = {
      status: "SUCCESS",
      tool: "search_repository",
      message: "Mock repository search executed successfully."
    };
    break;

  case "send_email":
    executionResult = {
      status: "SUCCESS",
      tool: "send_email",
      message: "Mock email operation executed successfully."
    };
    break;

  case "delete_database":
    executionResult = {
      status: "SUCCESS",
      tool: "delete_database",
      message: `Mock database deletion executed for: ${
        request.arguments?.path || "unknown"
      }`
    };
    break;

  default:
    executionResult = {
      status: "FAILED",
      tool: request.tool || "unknown",
      message: "Unknown tool. Mock execution stopped."
    };
}

return [
  {
    json: {
      ...request,

      execution: executionResult
    }
  }
];

return [
  {
    json: {
      ...$json,

      execution: {
        status: "BLOCKED",
        message: "Human rejected the requested operation."
      }
    }
  }
];

const data = $json;

const auditRecord = {
  timestamp: new Date().toISOString(),

  user_id: data.user_id || "unknown",

  agent_id: data.agent_id || "n8n-securemcp",

  mcp_server: data.mcp_server || "prototype",

  tool_name: data.tool || "unknown",

  arguments: data.arguments || {},

  arguments_hash: "prototype-hash",

  risk_score: data.risk?.score ?? data.risk_score ?? null,

  risk_level:
    data.risk?.level || data.risk_level || "UNKNOWN",

  authorization_decision:
    data.decision || "UNKNOWN",

  approval_status:
    data.approval_status || "NOT_REQUIRED",

  execution_result:
    data.execution || {
      status: "UNKNOWN"
    }
};

return [
  {
    json: auditRecord
  }
];
